import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename

app = Flask(__name__)

UPLOAD_DIR = '/var/spool/converter/input'
OUTPUT_DIR = '/var/spool/converter/output'
ALLOWED_EXTENSIONS = {'pdf', 'docx', 'xlsx', 'pptx'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_options(options_str):
    """Basic sanitization of LibreOffice conversion options."""
    blocked = ['macro', 'shell', 'exec']
    for b in blocked:
        if b in options_str.lower():
            return None
    return options_str

@app.route('/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    output_format = request.form.get('format', 'pdf')
    extra_options = request.form.get('options', '')

    # Sanitize user-provided options
    if extra_options:
        extra_options = sanitize_options(extra_options)
        if extra_options is None:
            return jsonify({'error': 'Invalid options'}), 400

    filename = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, filename)
    file.save(input_path)

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format}'
    if extra_options:
        cmd += f' {extra_options}'
    cmd += f' --outdir {OUTPUT_DIR} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        output_filename = filename.rsplit('.', 1)[0] + '.' + output_format
        output_path = os.path.join(OUTPUT_DIR, output_filename)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return jsonify({
            'status': 'success',
            'output': output_filename,
            'download_url': f'/download/{output_filename}'
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
